// 1. 领域事件定义
public class OrderCreatedEvent {
    private final String orderId;
    private final String customerId;
    private final BigDecimal totalAmount;
    private final LocalDateTime occurredAt;
    // immutable, constructor + getters
}

// 2. 事件发布 - Spring ApplicationEventPublisher
@Component
public class OrderDomainService {
    private final ApplicationEventPublisher eventPublisher;

    public OrderId createOrder(CreateOrderCmd cmd) {
        Order order = Order.create(cmd);
        orderRepository.save(order);
        // 发布领域事件
        eventPublisher.publishEvent(new OrderCreatedEvent(
            order.getId(),
            order.getCustomerId(),
            order.getTotalAmount(),
            LocalDateTime.now()
        ));
        return order.getId();
    }
}

// 3. 事件监听 - 解耦处理
@Component
public class InventoryEventHandler {
    @EventListener
    @Async
    public void handleOrderCreated(OrderCreatedEvent event) {
        // 扣减库存
        inventoryService.deduct(event.getItems());
    }
}

@Component
public class NotificationEventHandler {
    @EventListener
    @Async
    public void handleOrderCreated(OrderCreatedEvent event) {
        // 发送下单成功通知
        notificationService.send(event.getCustomerId(), "下单成功");
    }
}

// 4. Kafka事件驱动示例
@Service
public class KafkaEventPublisher {
    private final KafkaTemplate<String, Object> kafkaTemplate;

    public void publish(String topic, DomainEvent event) {
        kafkaTemplate.send(topic, event.getAggregateId(), event)
            .addCallback(
                result -> log.info("事件发布成功: {}", event),
                ex -> log.error("事件发布失败: {}", event, ex)
            );
    }
}

// 5. 幂等消费
@Component
public class IdempotentEventListener {
    private final EventProcessedRepository processedRepo;

    @KafkaListener(topics = "order-events")
    public void onEvent(DomainEvent event) {
        String eventId = event.getEventId();
        if (processedRepo.exists(eventId)) {
            log.info("事件已处理，跳过: {}", eventId);
            return;
        }
        // 处理事件
        processEvent(event);
        // 标记已处理
        processedRepo.markProcessed(eventId);
    }
}
